// --- Round-trip coverage via the builder (auto version + mask selection) ---

fn roundtrip(segments: Vec<Segment>, level: MicroEcLevel) {
    let enc = MicroQrEncoder::new();
    let sym = enc.build(segments, level).unwrap();
    let encoding = enc.encode(&sym).unwrap();
    let decoded = MicroQrDecoder::new().decode(&encoding).unwrap();
    assert_eq!(decoded.segments, sym.segments);
    assert_eq!(decoded.meta, sym.meta);
    assert_eq!(enc.encode(&decoded).unwrap(), encoding);
}

#[test]
fn builder_roundtrips() {
    roundtrip(
        vec![Segment::numeric(b"12345".to_vec())],
        MicroEcLevel::Detection,
    );
    roundtrip(vec![Segment::numeric(b"98765".to_vec())], MicroEcLevel::L);
    roundtrip(
        vec![Segment::alphanumeric(b"HELLO WORLD".to_vec())],
        MicroEcLevel::M,
    );
    roundtrip(vec![Segment::byte(b"anydcode".to_vec())], MicroEcLevel::M);
    roundtrip(
        vec![Segment::byte("héllo".as_bytes().to_vec())],
        MicroEcLevel::L,
    );
    roundtrip(vec![Segment::numeric(b"5".to_vec())], MicroEcLevel::L);
    roundtrip(vec![Segment::numeric(b"42".to_vec())], MicroEcLevel::M);
    roundtrip(
        vec![
            Segment::alphanumeric(b"AB".to_vec()),
            Segment::numeric(b"12345".to_vec()),
        ],
        MicroEcLevel::M,
    );
}

/// Only a zero *numeric* count is the terminator; an empty segment in another mode
/// (what `build_text("")` makes) is content and must survive the round trip, as
/// must whatever follows it.
#[test]
fn empty_segments_roundtrip() {
    roundtrip(vec![Segment::byte(Vec::new())], MicroEcLevel::L);
    roundtrip(
        vec![
            Segment::alphanumeric(Vec::new()),
            Segment::numeric(b"123".to_vec()),
        ],
        MicroEcLevel::M,
    );
    let enc = MicroQrEncoder::new();
    let sym = enc.build_text("", MicroEcLevel::L).unwrap();
    let encoding = enc.encode(&sym).unwrap();
    let decoded = MicroQrDecoder::new().decode(&encoding).unwrap();
    assert_eq!(decoded, sym);
}

/// Numeric mode's indicator is all zeros, so an empty numeric segment is bit-for-bit
/// the terminator: a reader stops there. Encoding one used to succeed and silently
/// drop every segment after it; it must be refused, at any version and position.
#[test]
fn empty_numeric_segment_is_rejected_not_truncated() {
    let enc = MicroQrEncoder::new();
    let empty = || Segment::numeric(Vec::new());
    let digits = || Segment::numeric(b"12".to_vec());
    for (version, level) in [
        (MicroVersion::M1, MicroEcLevel::Detection),
        (MicroVersion::M2, MicroEcLevel::L),
        (MicroVersion::M3, MicroEcLevel::M),
        (MicroVersion::M4, MicroEcLevel::Q),
    ] {
        for segments in [
            vec![empty()],
            vec![empty(), digits()],
            vec![digits(), empty(), digits()],
        ] {
            assert!(enc.build(segments.clone(), level).is_err(), "{version:?}");
            let pinned = Symbol::new(
                Symbology::MicroQrCode,
                segments,
                SymbolMeta::MicroQr(meta(version, level, 0)),
            );
            assert!(
                matches!(enc.encode(&pinned), Err(anyd::Error::InvalidData { .. })),
                "{version:?}"
            );
        }
        assert!(enc.build_numeric(b"", level).is_err());
        // No segments at all is still a valid (empty) symbol.
        let sym = enc.build(Vec::new(), level).unwrap();
        let decoded = MicroQrDecoder::new()
            .decode(&enc.encode(&sym).unwrap())
            .unwrap();
        assert_eq!(decoded, sym);
    }
}

#[test]
fn survives_correctable_error_m4() {
    // M4-Q corrects up to ~25%. Flip a single data module and still recover.
    let enc = MicroQrEncoder::new();
    let sym = enc
        .build(
            vec![Segment::alphanumeric(b"OK123".to_vec())],
            MicroEcLevel::Q,
        )
        .unwrap();
    let Encoding::Matrix(mut m) = enc.encode(&sym).unwrap() else {
        panic!("expected matrix");
    };
    // Flip an interior data module.
    let v = m.get(10, 10);
    m.set(10, 10, !v);
    let decoded = MicroQrDecoder::new().decode(&Encoding::Matrix(m)).unwrap();
    assert_eq!(decoded.segments, sym.segments);
}

#[test]
fn rejects_non_microqr_symbol() {
    let sym = Symbol::new(
        Symbology::QrCode,
        vec![Segment::numeric(b"1".to_vec())],
        SymbolMeta::Generic,
    );
    assert!(MicroQrEncoder::new().encode(&sym).is_err());
}

#[test]
fn wrong_size_matrix_is_undecodable() {
    let m = BitMatrix::new(12, 12, 2);
    assert!(MicroQrDecoder::new().decode(&Encoding::Matrix(m)).is_err());
}

// --- Automatic mode selection in build_text ---

/// Build from text, assert version + segmentation, and require a full round trip.
fn assert_text_choice(text: &str, level: MicroEcLevel, version: MicroVersion, want: &[Segment]) {
    let enc = MicroQrEncoder::new();
    let sym = enc.build_text(text, level).unwrap();
    assert_eq!(sym.segments, want, "unexpected segmentation for {text:?}");
    match &sym.meta {
        SymbolMeta::MicroQr(m) => assert_eq!(m.version, version, "version for {text:?}"),
        _ => panic!("missing MicroQrMeta"),
    }
    let encoding = enc.encode(&sym).unwrap();
    let decoded = MicroQrDecoder::new().decode(&encoding).unwrap();
    assert_eq!(decoded.segments, sym.segments);
    assert_eq!(enc.encode(&decoded).unwrap(), encoding);
}

#[test]
fn build_text_digits_fit_m1() {
    assert_text_choice(
        "12345",
        MicroEcLevel::Detection,
        MicroVersion::M1,
        &[Segment::numeric(b"12345".to_vec())],
    );
}

#[test]
fn build_text_alphanumeric_fits_m2() {
    assert_text_choice(
        "HELLO",
        MicroEcLevel::L,
        MicroVersion::M2,
        &[Segment::alphanumeric(b"HELLO".to_vec())],
    );
}

#[test]
fn build_text_lowercase_needs_byte_and_m3() {
    assert_text_choice(
        "hello",
        MicroEcLevel::L,
        MicroVersion::M3,
        &[Segment::byte(b"hello".to_vec())],
    );
}

#[test]
fn build_text_mixed_splits() {
    // Digits split out of the alphanumeric run once the run is long enough.
    let enc = MicroQrEncoder::new();
    let sym = enc.build_text("AB0123456789", MicroEcLevel::L).unwrap();
    let flat: Vec<u8> = sym.segments.iter().flat_map(|s| s.data.clone()).collect();
    assert_eq!(flat, b"AB0123456789".to_vec());
    let encoding = enc.encode(&sym).unwrap();
    let decoded = MicroQrDecoder::new().decode(&encoding).unwrap();
    assert_eq!(decoded.segments, sym.segments);
}

/// The heap-free `encode_into` path reproduces `build` + `Encode` exactly, both with
/// pinned parameters and when choosing version and mask itself.
#[test]
fn encode_into_matches_encode() {
    use anyd::output::BitMatrix;
    use anyd::segment::SegmentView;

    let enc = MicroQrEncoder::new();
    let mut storage = [0u8; MicroQrEncoder::MAX_BUFFER_LEN];
    for text in [
        "",
        "7",
        "01234567",
        "HELLO WORLD",
        "Micro QR!",
        "0123456789012345678901234567890123",
    ] {
        for level in [
            MicroEcLevel::Detection,
            MicroEcLevel::L,
            MicroEcLevel::M,
            MicroEcLevel::Q,
        ] {
            let Ok(symbol) = enc.build_text(text, level) else {
                continue;
            };
            let Encoding::Matrix(expected) = enc.encode(&symbol).unwrap() else {
                panic!("Micro QR encodes to a matrix");
            };
            let SymbolMeta::MicroQr(meta) = symbol.meta else {
                panic!("Micro QR meta")
            };
            let views: Vec<SegmentView<'_>> = symbol.segments.iter().map(|s| s.view()).collect();

            let (grid, pinned) = enc
                .encode_into(
                    &views,
                    level,
                    Some(meta.version),
                    Some(meta.mask),
                    &mut storage,
                )
                .unwrap();
            assert_eq!(grid, expected);
            assert_eq!(pinned, meta);

            let (grid, auto) = enc
                .encode_into(&views, level, None, None, &mut storage)
                .unwrap();
            assert_eq!(grid, expected);
            assert_eq!(auto, meta);

            let len = MicroQrEncoder::buffer_len(meta.version);
            assert!(
                enc.encode_into(&views, level, None, None, &mut storage[..len])
                    .is_ok()
            );
            let err = enc.encode_into(&views, level, None, None, &mut storage[..len - 1]);
            assert!(matches!(err, Err(anyd::Error::Capacity { .. })));
        }
    }

    // Unsupported version/level pairs and oversized data are errors, not panics.
    let digits = [SegmentView::numeric(b"123")];
    let err = enc.encode_into(
        &digits,
        MicroEcLevel::Q,
        Some(MicroVersion::M2),
        None,
        &mut storage,
    );
    assert!(matches!(err, Err(anyd::Error::InvalidParameter { .. })));
    let long = [SegmentView::byte(&[b'x'; 40])];
    let err = enc.encode_into(&long, MicroEcLevel::L, None, None, &mut storage);
    assert!(matches!(err, Err(anyd::Error::Capacity { .. })));

    // Single-mode convenience round-trips through the decoder.
    let (grid, meta) = enc
        .encode_text_into(b"HELLO", MicroEcLevel::L, &mut storage)
        .unwrap();
    let decoded = MicroQrDecoder::new()
        .decode(&Encoding::Matrix(BitMatrix::from(&grid)))
        .unwrap();
    assert_eq!(decoded.text().as_deref(), Some("HELLO"));
    assert_eq!(decoded.meta, SymbolMeta::MicroQr(meta));
}

/// Kanji mode round-trips, and a Shift-JIS trail byte below 0x40 (which would alias
/// another character's 13-bit value) is rejected rather than silently re-mapped.
#[test]
fn kanji_roundtrips_and_rejects_bad_trail_byte() {
    roundtrip(
        vec![Segment::kanji(vec![0x93, 0x5F, 0xE4, 0xAA])],
        MicroEcLevel::L,
    );
    let bad = vec![Segment::kanji(vec![0x82, 0x00])];
    assert!(MicroQrEncoder::new().build(bad, MicroEcLevel::L).is_err());
}

/// M1's two EC codewords are error *detection* only (ISO/IEC 18004 Table 9: p = 2,
/// no correction). Using them to correct turned ~2.6% of two-module damage into a
/// confidently wrong payload; every one- and two-module error must be detected.
#[test]
fn m1_detects_errors_and_never_miscorrects() {
    let enc = MicroQrEncoder::new();
    let sym = enc
        .build(
            vec![Segment::numeric(b"12345".to_vec())],
            MicroEcLevel::Detection,
        )
        .unwrap();
    let Encoding::Matrix(clean) = enc.encode(&sym).unwrap() else {
        panic!("expected matrix");
    };
    let data_modules: Vec<(usize, usize)> = (1..11)
        .flat_map(|y| (1..11).map(move |x| (x, y)))
        .filter(|&(x, y)| x > 8 || y > 8)
        .collect();
    assert_eq!(data_modules.len(), 36);
    for (i, &a) in data_modules.iter().enumerate() {
        for &b in &data_modules[i..] {
            let mut m = clean.clone();
            for (x, y) in [a, b] {
                let v = m.get(x, y);
                m.set(x, y, !v);
            }
            if a == b {
                continue; // flipped twice: the clean symbol
            }
            let got = MicroQrDecoder::new().decode(&Encoding::Matrix(m));
            assert!(got.is_err(), "damage at {a:?}+{b:?} decoded as {got:?}");
        }
        let mut m = clean.clone();
        m.set(a.0, a.1, !clean.get(a.0, a.1));
        assert!(MicroQrDecoder::new().decode(&Encoding::Matrix(m)).is_err());
    }
}

// --- Capacity boundaries, error paths, parameter ranges ---

/// ISO/IEC 18004 Table 7, Micro QR rows: the longest numeric / alphanumeric / byte
/// / Kanji segment per version and level (0 = mode not available there). zint 2.16
/// accepts exactly the same lengths.
const CAPACITY: [(MicroVersion, MicroEcLevel, [usize; 4]); 8] = [
    (MicroVersion::M1, MicroEcLevel::Detection, [5, 0, 0, 0]),
    (MicroVersion::M2, MicroEcLevel::L, [10, 6, 0, 0]),
    (MicroVersion::M2, MicroEcLevel::M, [8, 5, 0, 0]),
    (MicroVersion::M3, MicroEcLevel::L, [23, 14, 9, 6]),
    (MicroVersion::M3, MicroEcLevel::M, [18, 11, 7, 4]),
    (MicroVersion::M4, MicroEcLevel::L, [35, 21, 15, 9]),
    (MicroVersion::M4, MicroEcLevel::M, [30, 18, 13, 8]),
    (MicroVersion::M4, MicroEcLevel::Q, [21, 13, 9, 5]),
];

fn segment_of(mode: usize, len: usize) -> Segment {
    match mode {
        0 => Segment::numeric(vec![b'8'; len]),
        1 => Segment::alphanumeric(vec![b'%'; len]),
        2 => Segment::byte(vec![0xB7; len]),
        _ => Segment::kanji([0xE4, 0xAA].repeat(len)),
    }
}

/// At every version and level, in every mode: the Table 7 maximum fits (the
/// terminator is shortened or dropped) and round-trips, one character more is a
/// capacity error, and a mode the version lacks is refused outright.
#[test]
fn capacity_boundaries_at_every_version_and_level() {
    let enc = MicroQrEncoder::new();
    for (version, level, maxima) in CAPACITY {
        for (mode, max) in maxima.into_iter().enumerate() {
            let what = format!("{version:?}-{level:?} mode {mode}");
            let pinned = |len| symbol(segment_of(mode, len), meta(version, level, 2));
            if max == 0 {
                assert!(
                    matches!(enc.encode(&pinned(1)), Err(anyd::Error::InvalidData { .. })),
                    "{what}"
                );
                continue;
            }
            for len in 1..=max {
                let full = pinned(len);
                let encoding = enc.encode(&full).unwrap();
                assert_eq!(
                    MicroQrDecoder::new().decode(&encoding).unwrap(),
                    full,
                    "{what} len {len}"
                );
            }
            assert!(
                matches!(
                    enc.encode(&pinned(max + 1)),
                    Err(anyd::Error::Capacity { .. })
                ),
                "{what}"
            );
        }
    }
    // The builder moves to the next version exactly at the boundary, and gives up
    // past M4.
    let version_of = |s: &Symbol| match &s.meta {
        SymbolMeta::MicroQr(m) => m.version,
        _ => panic!("expected MicroQrMeta"),
    };
    for (len, want) in [
        (10, Some(MicroVersion::M2)),
        (11, Some(MicroVersion::M3)),
        (23, Some(MicroVersion::M3)),
        (24, Some(MicroVersion::M4)),
        (35, Some(MicroVersion::M4)),
        (36, None),
    ] {
        let built = enc.build_numeric(&vec![b'1'; len], MicroEcLevel::L);
        assert_eq!(built.as_ref().ok().map(version_of), want, "{len} digits");
        if want.is_none() {
            assert!(matches!(built, Err(anyd::Error::Capacity { .. })));
        }
    }
}

#[test]
fn encoder_rejects_what_it_cannot_represent() {
    let enc = MicroQrEncoder::new();
    let one = || Segment::numeric(b"1".to_vec());
    // Levels a version does not define.
    for (version, level) in [
        (MicroVersion::M1, MicroEcLevel::L),
        (MicroVersion::M2, MicroEcLevel::Detection),
        (MicroVersion::M2, MicroEcLevel::Q),
        (MicroVersion::M3, MicroEcLevel::Q),
        (MicroVersion::M4, MicroEcLevel::Detection),
    ] {
        assert!(
            matches!(
                enc.encode(&symbol(one(), meta(version, level, 0))),
                Err(anyd::Error::InvalidParameter { .. })
            ),
            "{version:?}-{level:?}"
        );
    }
    // Content no mode can carry, and ECI, which Micro QR does not have.
    for segment in [
        Segment::numeric(b"1a".to_vec()),
        Segment::alphanumeric(b"a".to_vec()),
        Segment::kanji(vec![0x93]),
        Segment::kanji(vec![0x41, 0x42]),
        Segment::eci(26),
    ] {
        let pinned = symbol(segment.clone(), meta(MicroVersion::M4, MicroEcLevel::L, 0));
        assert!(
            matches!(enc.encode(&pinned), Err(anyd::Error::InvalidData { .. })),
            "{segment:?}"
        );
        assert!(enc.build(vec![segment], MicroEcLevel::L).is_err());
    }
    // The right symbology without Micro QR metadata.
    let generic = Symbol::new(Symbology::MicroQrCode, vec![one()], SymbolMeta::Generic);
    assert!(matches!(
        enc.encode(&generic),
        Err(anyd::Error::InvalidParameter { .. })
    ));
    // A grid buffer too small for the version.
    let views = [anyd::segment::SegmentView::numeric(b"1")];
    let mut short = vec![0u8; MicroQrEncoder::buffer_len(MicroVersion::M2) - 1];
    assert!(matches!(
        enc.encode_into(&views, MicroEcLevel::L, None, None, &mut short),
        Err(anyd::Error::Capacity { .. })
    ));
    // Detection is M1 only, and M1 is numeric only.
    assert!(enc.build_text("A", MicroEcLevel::Detection).is_err());
    assert!(enc.build_text("123456", MicroEcLevel::Detection).is_err());
}

#[test]
fn decoder_rejects_non_micro_qr_inputs() {
    let dec = MicroQrDecoder::new();
    let linear = Encoding::Linear(anyd::output::LinearPattern::new());
    assert!(matches!(
        dec.decode(&linear),
        Err(anyd::Error::Unsupported { .. })
    ));
    for (w, h) in [(0, 0), (11, 13), (9, 9), (19, 19), (21, 21)] {
        assert!(
            dec.decode_matrix(&BitMatrix::new(w, h, 2)).is_err(),
            "{w}x{h}"
        );
    }
    // The format information names the version too; it must agree with the grid.
    // An M2 symbol's format strip transplanted onto an M3 symbol does not.
    let enc = MicroQrEncoder::new();
    let grid = |version, level| {
        let sym = symbol(Segment::numeric(b"123".to_vec()), meta(version, level, 0));
        let Encoding::Matrix(m) = enc.encode(&sym).unwrap() else {
            panic!("expected matrix");
        };
        m
    };
    let m2 = grid(MicroVersion::M2, MicroEcLevel::L);
    let mut m3 = grid(MicroVersion::M3, MicroEcLevel::L);
    for i in 1..=8 {
        m3.set(8, i, m2.get(8, i));
        m3.set(i, 8, m2.get(i, 8));
    }
    assert!(matches!(
        dec.decode_matrix(&m3),
        Err(anyd::Error::Undecodable { .. })
    ));
}

/// The 15-bit format word is BCH(15,5): any three damaged modules are corrected,
/// for all eight symbol numbers.
#[test]
fn format_information_survives_three_errors() {
    let enc = MicroQrEncoder::new();
    for (i, (version, level, _)) in CAPACITY.into_iter().enumerate() {
        let sym = symbol(Segment::numeric(b"271".to_vec()), meta(version, level, 3));
        let Encoding::Matrix(clean) = enc.encode(&sym).unwrap() else {
            panic!("expected matrix");
        };
        // Format modules: column 8 rows 1..=8, then row 8 columns 7..=1.
        let cells: Vec<(usize, usize)> = (1..=8)
            .map(|y| (8, y))
            .chain((1..=7).rev().map(|x| (x, 8)))
            .collect();
        assert_eq!(cells.len(), 15);
        for a in 0..13 {
            let mut m = clean.clone();
            for k in [a, a + 1 + i % 2, (a + 7) % 15] {
                let (x, y) = cells[k];
                m.set(x, y, !clean.get(x, y));
            }
            assert_eq!(
                MicroQrDecoder::new().decode_matrix(&m).as_ref(),
                Ok(&sym),
                "{version:?}-{level:?} from {a}"
            );
        }
    }
}

#[test]
fn parameter_types_validate_their_ranges() {
    assert!(MicroVersion::from_number(0).is_none() && MicroVersion::from_number(5).is_none());
    for n in 1..=4u8 {
        let version = MicroVersion::from_number(n).unwrap();
        assert_eq!(version.number(), n);
        assert_eq!(version.size(), 9 + 2 * n as usize);
        assert_eq!(MicroVersion::from_size(version.size()), Some(version));
        assert!(MicroQrEncoder::buffer_len(version) <= MicroQrEncoder::MAX_BUFFER_LEN);
    }
    for size in [0, 9, 12, 19, 21] {
        assert!(MicroVersion::from_size(size).is_none());
    }
    assert!(MicroMask::new(4).is_none());
    assert_eq!(MicroMask::new(3).unwrap().index(), 3);
}
